def main():
    N = int(input())
    adjacency_matrix = []
    for _ in range(N):
        row = list(map(int, input().split()))
        adjacency_matrix.append(row)

    for i in range(1, N + 1):
        connected_vertices = []
        for j in range(1, N + 1):
            if adjacency_matrix[i - 1][j - 1] == 1:
                connected_vertices.append(j)
        print(connected_vertices)
